dtsPropsFor.LabCard:
/** A lab catalog item. */
lab: {
  id: string;
  title: string;
  description: string;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  duration_min: number;
  tags: string[];
  step_count: number;
  vm_type?: string;
};

dtsPropsFor.SessionTimer:
/** ISO-8601 session expiry timestamp; the timer counts down to it. */
expiresAt: string;
/** Called once when the countdown reaches zero. */
onExpire?: () => void;

dtsPropsFor.StepList:
steps: { id: number; title: string; description: string; commands?: string[] }[];
/** Returns the progress status for a given step id. */
statusOf: (id: number) => 'pending' | 'active' | 'validating' | 'passed' | 'failed';
/** The currently focused step id (highlighted). */
currentId?: number;
onSelect: (id: number) => void;

dtsPropsFor.AiTutorPanel:
sessionId: string;
stepId: number;
/** Supplies the recent terminal output appended to the hint request. */
getTerminalTail?: () => string;

dtsPropsFor.LabTerminal:
/** Session-scoped WebSocket path for the lab VM serial console. */
terminalPath: string;
/** Tailwind height class for the terminal viewport. */
heightClass?: string;
onOutput?: (chunk: string) => void;

dtsPropsFor.LabWorkspace:
sessionId: string;
terminalPath: string;
/** code-server proxy path for the IDE (VS Code) tab. */
idePath: string;
heightClass?: string;
onTerminalOutput?: (chunk: string) => void;

dtsPropsFor.LabSession:
sessionId: string;
lab: {
  id: string;
  title: string;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  steps?: { id: number; title: string; description: string; commands?: string[] }[];
  environment?: string;
  ide?: boolean;
  [key: string]: unknown;
};
/** Skip the post-ready boot grace period (resume of an already-ready session). */
skipBootGrace?: boolean;
